import{_ as t,c as n,o as s,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易傳燈","description":"易傳燈 - 易傳燈","frontmatter":{"title":"易傳燈","description":"易傳燈 - 易傳燈"},"headers":[],"relativePath":"classics/yichuandeng/001.md","filePath":"classics/yichuandeng/001.md"}'),r={name:"classics/yichuandeng/001.md"};function c(i,a,o,d,p,u){return s(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"易傳燈",tabindex:"-1"},[l("易傳燈 "),e("a",{class:"header-anchor",href:"#易傳燈","aria-label":"Permalink to “易傳燈”"},"​")],-1),e("p",null,"有序 是書舊署徐總幹撰，而不著名。其子序謂其父嘗師事呂祖謙、唐仲友，所學似尚有稟承。顧取釋氏傳燈語為經解標題，謬盩甚矣。其言君子小人吉凶陰陽之義，頗有闡發，而所論河圖數象，牽附九宮，則又乖於正道。蓋其書純駁參半，乃指斥後學差誤，得無責人則明，而責己則昏歟？以其裒輯於散帙之中，亦云希覯，錄備四庫，庶幾瑕瑜不掩。系詩簡端譏之，正所以惜之也。",-1),e("p",null,"徐氏隱名，故以何標題，想亦自知過。本來畫卦由古聖，胡乃傳燈擬梵陀。學述東萊道未見，習沿永叔語傷訛。明雲後學多差誤，可識其人差已多。欽定四庫全書經部一易傳燈四卷易類提要",-1),e("p",null,"臣 等謹案：易傳燈一書，諸家書目俱不著錄，朱彝尊經義考亦不載其名。惟永樂大典散見於谷卦之中，題其官曰徐總幹，而不著名字。又載其子子東序，謂其父嘗師事呂祖謙、唐仲友。考宋史，徐僑嘗受業於呂祖謙，著讀易記、尚書括旨等書。祖謙門人又有徐侃、徐倬序，無明文，不能定其為誰也。「傳燈」本釋氏之語，乃取之以名經解，殊為乖刺。又謂系詞下傳「易之為書」三章，皆漢儒易緯之文，訛為夫子之作，以誑後世，亦沿歐陽修之誤。又謂聖人觀河圖有數有象，以從橫十五之妙，配乾坤九六之數，白紫者吉，黃黑者兇。是直以易數為五行家言，尤未免於駁雜。然其八卦總論十六篇，參互以求，頗能得易之類例。如曰大壯、大有、夬、乾，乾在乾、兌、離、震之下者也。乾九三曰「君子」，而餘卦九三皆有「君子」「小人」之詞，以君子在重剛中，君子則吉，小人則兇，故分別言之也。其處於巽、坎、艮、坤之下者，曰小畜、大畜、需、泰，凡九三上遇陰爻，皆有畏謹之義，剖析更為微細。又謂易之取象，該三代制度。如比九五言「王用三驅」，見王田不合圍，三面而驅之禮。巽九二言「史巫紛若」，見古有太史、男巫、女巫之制。論易、禮之相通，亦有證據。蓋一知半解，可取者亦頗不乏。雖有絲麻，無棄菅蒯，固說易者之所旁採爾。乾隆四十六年九月恭校上。",-1),e("p",null,"總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。原序",-1),e("p",null,"先君總幹幼年習聲律，自後喜經術而厭雕篆，由是再更六典。紹興初，嘗師東萊呂先生 祖謙、 說齋唐先生 仲友。 從宋先生 真卿 書堂，因見壁間伏羲先天八卦圖象，篤志學易，佩服師訓，蚤夜究心。嘗應試漕闈，兩預薦書，皆以是經。先君重道義而輕利祿，薄奔競而安恬退，隱居易堂，精研先天之學，以六十四卦三百八十四爻系國家興衰治亂之時用。寶慶間，遂作周易大義，繼作衍義，續作傳燈，究先哲之微言，期後學於同歸。去「爻應互體」等說，越數十載方脫稿。先君初意，為子孫眾多，皆欲淑以斯文，故作是書，非欲自侈其學也。愚不敢私，即取而公之，悉鋟諸梓，不惟不秘先君之志，而先君之學亦於是乎傳矣。寶祐丁巳仲春既望，季子徐子東敬系。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
